 private static boolean sensitive(String s){return Pattern.compile("(sk-|bearer|api[_-]?key|password|authorization|token[=:]|https?://|[a-z]:[\\\\/])",Pattern.CASE_INSENSITIVE).matcher(s).find();}
 private static String text(JSONObject o,String key,int max)throws Exception{Object value=o.opt(key);need(value==null||value==JSONObject.NULL||value instanceof String,"文本字段类型无效");String s=value instanceof String?(String)value:"";need(s.length()<=max,"文本字段超过范围");return sensitive(s)?"[敏感详情已排除]":s;}
