 private static String state(JSONObject o,String key,String... options)throws Exception{Object v=o.opt(key);need(v==null||v instanceof String,"状态字段无效");return Arrays.asList(options).contains(v)?(String)v:"unknown";}
 private static Object time(JSONObject o,String key)throws Exception{Object v=o.opt(key);if(v==null||v==JSONObject.NULL||"".equals(v))return JSONObject.NULL;need(v instanceof String&&((String)v).length()<=40,"时间字段无效");try{OffsetDateTime.parse((String)v);}catch(Exception e){throw new Exception("时间字段无效");}return v;}
 public static JSONObject empty()throws Exception{return new JSONObject().put("schema","native-data-source-status/v1").put("generatedAt",JSONObject.NULL).put("inventoryScope","host-injected-only").put("completeInventory",false).put("records",new JSONArray());}
 public static JSONObject snapshot(JSONObject input)throws Exception{need(input.optString("schema").equals("native-data-source-status/v1")&&input.opt("records") instanceof JSONArray,"不是本机数据源状态格式");JSONArray records=input.getJSONArray("records"),safe=new JSONArray();need(records.length()<=1000,"来源记录超过1000条");Set<String> seen=new HashSet<>();for(int n=0;n<records.length();n++){JSONObject o=records.optJSONObject(n);need(o!=null,"来源记录无效");String provider=id(o,"provider",80),product=state(o,"product","quote","intraday","kline","auction","funds","industry","concept","news","indices","breadth","level2"),grain=id(o,"granularity",40);need(!product.equals("unknown")&&o.opt("target") instanceof JSONObject,"产品或精确目标缺失");JSONObject t=o.getJSONObject("target");String kind=state(t,"kind","instrument","board","market","news","scope");need(!kind.equals("unknown"),"目标种类无效");JSONObject target=new JSONObject().put("kind",kind);if(kind.equals("board")){target.put("provider",id(t,"provider",80)).put("taxonomy",state(t,"taxonomy","industry","concept")).put("code",id(t,"code",80));need(!target.getString("taxonomy").equals("unknown"),"板块来源或分类不匹配");}else{String targetId=id(t,"id",160);if(kind.equals("instrument"))need(targetId.matches("(SH|SZ|BJ|HK|US):(stock|etf|index|fund):[A-Za-z0-9._-]{1,16}"),"证券须使用完整市场/类型/代码身份");target.put("id",targetId);}
  JSONObject r=new JSONObject().put("provider",provider).put("product",product).put("granularity",grain).put("target",target).put("route",text(o,"route",60)).put("acquisition",state(o,"acquisition","available","partial","unavailable","unknown")).put("cache",state(o,"cache","fresh","cached","stale","none","unknown")).put("persistence",state(o,"persistence","saved","pending","failed","unknown")).put("evidenceKind",state(o,"evidenceKind","public-snapshot","vendor-classified","local-estimate","local-sample","imported-unverified","unknown")).put("authorization","unknown").put("sustainedRealtime","unknown").put("capability",state(o,"capability","observed-once","declared","unsupported","unknown")).put("error",text(o,"error",1000)).put("note",text(o,"note",1000)).put("sourceTiming",text(o,"sourceTiming",500)).put("sampleScope",text(o,"sampleScope",500)).put("coverageScope",text(o,"coverageScope",100)).put("adjustment",state(o,"adjustment","qfq","hfq","none","unknown"));for(String k:new String[]{"sourceTime","fetchedAt","persistedAt","attemptedAt","startedAt"})r.put(k,time(o,k));String date=text(o,"dataDate",10);if(!date.isEmpty())try{need(date.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"),"数据日期无效");LocalDate.parse(date);}catch(Exception e){throw new Exception("数据日期无效");}r.put("dataDate",date.isEmpty()?JSONObject.NULL:date);
  for(String k:new String[]{"rowCount","declaredTotal","elapsedMs","pageCount"}){Object value=o.opt(k);if(value==null||value==JSONObject.NULL)r.put(k,JSONObject.NULL);else{need(value instanceof Number,"计数字段无效");double count=((Number)value).doubleValue();need(Double.isFinite(count)&&count>=0&&count<=9007199254740991.&&count==Math.floor(count),"计数字段无效");r.put(k,value);}}Object complete=o.opt("coverageComplete");need(complete==null||complete==JSONObject.NULL||complete instanceof Boolean,"覆盖字段无效");r.put("coverageComplete",complete==null?JSONObject.NULL:complete);
  String link=o.optString("sourceUrl",""),safeUrl="";try{URI u=new URI(link);if(link.length()<=512&&!link.contains("%")&&"https".equals(u.getScheme())&&u.getHost()!=null&&u.getUserInfo()==null&&u.getRawQuery()==null&&u.getRawFragment()==null&&!Pattern.compile("(sk-|bearer|api[_-]?key|password|token)",Pattern.CASE_INSENSITIVE).matcher(link).find())safeUrl=u.toASCIIString();}catch(Exception ignored){}r.put("sourceUrl",safeUrl.isEmpty()?JSONObject.NULL:safeUrl);if(r.getString("capability").equals("observed-once")&&(r.isNull("fetchedAt")||(!r.getString("acquisition").equals("available")&&!r.getString("acquisition").equals("partial"))))r.put("capability","unknown");
  String targetKey=kind+"|"+(kind.equals("board")?target.getString("provider")+"|"+target.getString("taxonomy")+"|"+target.getString("code"):target.getString("id"));String key=hash((provider+"|"+product+"|"+grain+"|"+targetKey).getBytes(StandardCharsets.UTF_8));need(seen.add(key),"完整来源/产品/粒度/目标身份重复");r.put("key",key);safe.put(r);
 }JSONObject result=empty().put("generatedAt",time(input,"generatedAt")).put("records",safe);need(result.toString().getBytes(StandardCharsets.UTF_8).length<=1024*1024,"来源证据超过1MiB");return result;}
 static String hash(byte[] b)throws Exception{StringBuilder out=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(b))out.append(String.format(Locale.ROOT,"%02x",v&255));return out.toString();}
 public static JSONArray rows(JSONObject snapshot,JSONObject filters)throws Exception{JSONArray out=new JSONArray(),records=snapshot.getJSONArray("records");String search=filters.optString("search","").trim().toLowerCase(Locale.ROOT);for(int n=0;n<records.length();n++){JSONObject r=records.getJSONObject(n);boolean match=true;for(String k:new String[]{"provider","product","granularity","acquisition"}){String f=filters.optString(k,"");if(!f.isEmpty()&&!f.equals("*")&&!f.equals(r.getString(k)))match=false;}if(match&&(search.isEmpty()||title(r).toLowerCase(Locale.ROOT).contains(search)))out.put(r);}return out;}
 public static boolean canOpen(JSONObject r,Collection<String> allow)throws Exception{String route=r.optString("route",""),p=r.getString("product"),kind=r.getJSONObject("target").getString("kind");if(!allow.contains(route))return false;if(route.equals("detail")||route.equals("stock"))return kind.equals("instrument")&&Arrays.asList("quote","intraday","kline").contains(p);if(route.equals("auction"))return kind.equals("instrument")&&p.equals("auction");if(route.equals("capital")||route.equals("funds"))return p.equals("funds")&&Arrays.asList("instrument","market","scope").contains(kind);if(Arrays.asList("sector-watch","sectors","industry-discovery").contains(route))return Arrays.asList("industry","concept").contains(p)&&Arrays.asList("board","market","scope").contains(kind);if(route.equals("news"))return p.equals("news");if(route.equals("market")||route.equals("market-overview"))return Arrays.asList("indices","breadth","industry","concept").contains(p)&&Arrays.asList("market","scope").contains(kind);return false;}
 public static JSONObject navigation(JSONObject r)throws Exception{return new JSONObject(r.getJSONObject("target").toString()).put("sourceProvider",r.getString("provider")).put("product",r.getString("product")).put("granularity",r.getString("granularity")).put("adjustment",r.getString("adjustment")).put("evidenceKey",r.getString("key"));}
 public static String productName(String p){String[] codes={"quote","intraday","kline","auction","funds","industry","concept","news","indices","breadth","level2"},labels={"报价","分时","K线","竞价","资金","行业","概念","资讯","指数","市场宽度","Level-2"};for(int n=0;n<codes.length;n++)if(codes[n].equals(p))return labels[n];return p;}
 public static String title(JSONObject r)throws Exception{JSONObject t=r.getJSONObject("target");String target=t.getString("kind").equals("board")?t.getString("provider")+" / "+t.getString("taxonomy")+" / "+t.getString("code"):t.getString("id");return r.getString("provider")+" · "+productName(r.getString("product"))+" · "+stateName(r.getString("granularity"))+" · "+target;}
 public static String description(JSONObject r)throws Exception{StringBuilder out=new StringBuilder(title(r)).append("\n");String[] keys={"acquisition","cache","persistence","sourceTime","dataDate","fetchedAt","persistedAt","attemptedAt","evidenceKind","capability","rowCount","coverageComplete"},labels={"取得状态","缓存状态","本机保存","来源时间","数据日期","取得时间","保存时间","最近尝试","证据口径","能力证据","记录数","当前范围覆盖完整"};for(int n=0;n<keys.length;n++)out.append(labels[n]).append("：").append(r.isNull(keys[n])?"未知":stateName(r.get(keys[n]).toString())).append("\n");return out.append("L2 授权：未知；稳定实时能力：未知\n").append(r.getString("error")).append("\n").append(r.getString("note")).toString();}
 public static byte[] exportEvidence(JSONObject input,JSONObject filters)throws Exception{JSONObject safe=snapshot(input);safe.put("records",rows(safe,filters)).put("exportedAt",Instant.now().toString());return safe.toString(2).getBytes(StandardCharsets.UTF_8);}
